class CharacterChatPage extends StatefulWidget {
  final PresentationState? state;
  final bool busy;
  final String selectedAgent;
  final ValueChanged<String> onSelectAgent;
  final void Function(String message, String agent, List<Map<String, dynamic>> references) onSend;
  final VoidCallback onOpenTask;
  const CharacterChatPage({super.key,required this.state,required this.busy,required this.selectedAgent,required this.onSelectAgent,required this.onSend,required this.onOpenTask});
  @override State<CharacterChatPage> createState()=>_CharacterChatPageState();
}

class _CharacterChatPageState extends State<CharacterChatPage>{
 final input=TextEditingController(); final List<String> _localMessages=[]; final List<Map<String,dynamic>> _references=[];
 @override void dispose(){input.dispose();super.dispose();}
 void _send(){final text=input.text.trim();if(text.isEmpty||widget.busy)return;setState((){_localMessages.add(text);input.clear();});widget.onSend(text,widget.selectedAgent,List<Map<String,dynamic>>.from(_references));}
 void _sendChoice(String text){if(widget.busy)return;setState(()=>_localMessages.add(text));widget.onSend(text,widget.selectedAgent,List<Map<String,dynamic>>.from(_references));}
 Future<void> _attach() async{final result=await FilePicker.platform.pickFiles(withData:true,allowMultiple:false);if(result==null||result.files.isEmpty)return;final file=result.files.single;final bytes=file.bytes;if(bytes==null){_error('The selected file could not be read in the browser.');return;}if(bytes.length>4*1024*1024){_error('Reference files are limited to 4 MB each.');return;}setState(()=>_references.add({'name':file.name,'kind':_kind(file.extension),'size_bytes':bytes.length,'content_base64':base64Encode(bytes)}));}
 void _error(String text){if(!mounted)return;ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(text)));}
 @override Widget build(BuildContext context)=>LayoutBuilder(builder:(context,constraints){final narrow=constraints.maxWidth<900;return Container(color:CriterivoxTheme.of(context).page,child:Row(children:[if(!narrow)SizedBox(width:235,child:_CharacterPicker(selected:widget.selectedAgent,onSelect:widget.onSelectAgent)),Expanded(child:_Conversation(state:widget.state,busy:widget.busy,target:widget.selectedAgent,input:input,onSend:_send,onChoice:_sendChoice,onAttach:_attach,references:_references,localMessages:_localMessages,onOpenTask:widget.onOpenTask,onSelectAgent:widget.onSelectAgent)),if(!narrow)SizedBox(width:290,child:_Context(state:widget.state,target:widget.selectedAgent,onOpenTask:widget.onOpenTask))]));});
 String _kind(String? extension){switch(extension?.toLowerCase()){case 'csv':return 'dataset';case 'png':case 'jpg':case 'jpeg':case 'webp':return 'image';case 'pdf':case 'txt':case 'doc':case 'docx':return 'document';default:return 'file';}}
}

